INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5388239, 774197, 63633, '<td valign="top">This is a really lovely image, but it doesn''t really say "forgotten" to me.</td>', 'This is a really lovely image, but it doesn''t really say "forgotten" to me.', '2009-03-18 00:42:17.000000', NULL, 1),
(5388241, 774148, 63633, '<td valign="top">A great take on the challenge. I love the ''colours of old'' you have captured in this image.</td>', 'A great take on the challenge. I love the ''colours of old'' you have captured in this image.', '2009-03-18 00:44:11.000000', NULL, 1),
(5388242, 773147, 63633, '<td valign="top">A lovely clean image, will appeal well to DPC voters I think. I like it!</td>', 'A lovely clean image, will appeal well to DPC voters I think. I like it!', '2009-03-18 00:45:53.000000', NULL, 1),
(5388245, 774202, 63633, '<td valign="top">This is a pretty scene, but I find the composition a bit awkward and the detail lacking. The link to the challenge seems a bit tenuous. Sorry, but I feel obliged to explain my low vote.</td>', 'This is a pretty scene, but I find the composition a bit awkward and the detail lacking. The link to the challenge seems a bit tenuous. Sorry, but I feel obliged to explain my low vote.', '2009-03-18 00:48:22.000000', NULL, 1),
(5388248, 774155, 63633, '<td valign="top">This ties in well with the theme, and the light is really nice. I''m not sure that the negative space adds to this though.</td>', 'This ties in well with the theme, and the light is really nice. I''m not sure that the negative space adds to this though.', '2009-03-18 00:50:41.000000', NULL, 1),
(5388250, 774336, 63633, '<td valign="top">Being Australian, I don''t know the history behind this, but I gather it''s similar to our 1 dollar notes, and our one and two cent coins. Great idea! I find the tonal range in this a bit muddy though.</td>', 'Being Australian, I don''t know the history behind this, but I gather it''s similar to our 1 dollar notes, and our one and two cent coins. Great idea! I find the tonal range in this a bit muddy though.', '2009-03-18 00:52:43.000000', NULL, 1),
(5388251, 774346, 83313, '<td valign="top">Used one in high school, just a few years before calculators got really cheap. Can''t remember how to use one now, though.</td>', 'Used one in high school, just a few years before calculators got really cheap. Can''t remember how to use one now, though.', '2009-03-18 00:52:43.000000', NULL, 1),
(5388252, 773762, 83313, '<td valign="top">Colors come of a little flat, but that may be intentional. Nice pleasing scene, however.</td>', 'Colors come of a little flat, but that may be intentional. Nice pleasing scene, however.', '2009-03-18 00:55:17.000000', NULL, 1),
(5388253, 774002, 83313, '<td valign="top">Keds? Of course. Status symbol when I was in elementary school.</td>', 'Keds? Of course. Status symbol when I was in elementary school.', '2009-03-18 00:56:26.000000', NULL, 1),
(5388254, 774125, 83313, '<td valign="top">That "cargo rack" was useful for carrying a friend. Useful, but not terribly safe.</td>', 'That "cargo rack" was useful for carrying a friend. Useful, but not terribly safe.', '2009-03-18 00:57:28.000000', NULL, 1),
(5388256, 774156, 83313, '<td valign="top">Nice and grungy. Good treatment.</td>', 'Nice and grungy. Good treatment.', '2009-03-18 00:58:26.000000', NULL, 1),
(5388259, 774238, 83313, '<td valign="top">I don''t know what to say. I feel embarrassed over relishing in all the nostalgia of the other pics.</td>', 'I don''t know what to say. I feel embarrassed over relishing in all the nostalgia of the other pics.', '2009-03-18 01:01:05.000000', NULL, 1),
(5388263, 773771, 83313, '<td valign="top">Gen. Doolittle''s Tokyo raiders. Nice crisp shot.  Great old warbird.</td>', 'Gen. Doolittle''s Tokyo raiders. Nice crisp shot.  Great old warbird.', '2009-03-18 01:05:16.000000', NULL, 1),
(5388265, 774351, 83313, '<td valign="top">Never had one of these, but had a few friends with one. I started with a Tandy 1000sx.</td>', 'Never had one of these, but had a few friends with one. I started with a Tandy 1000sx.', '2009-03-18 01:07:18.000000', NULL, 1),
(5388267, 772809, 63633, '<td valign="top">Ah, those were the days! I find the image a bit too grey (no real blacks or whites), but a good idea.</td>', 'Ah, those were the days! I find the image a bit too grey (no real blacks or whites), but a good idea.', '2009-03-18 01:08:19.000000', NULL, 1),
(5388270, 774167, 83313, '<td valign="top">Are you suggesting that candy dots are plastic? Or maybe just that they taste that way?</td>', 'Are you suggesting that candy dots are plastic? Or maybe just that they taste that way?', '2009-03-18 01:09:40.000000', NULL, 1),
(5388272, 774214, 63633, '<td valign="top">Wow, your perspective is fantastic - I assume the doll isn''t as big as it seems :) A great take on the challenge.</td>', 'Wow, your perspective is fantastic - I assume the doll isn''t as big as it seems :) A great take on the challenge.', '2009-03-18 01:10:55.000000', NULL, 1),
(5388279, 773265, 83313, '<td valign="top">Nice macro, but way too much JPEG compression for a shot with so much detail. With a 97k file size, you had a lot more overhead and could have avoided a slightly grainy look to this.</td>', 'Nice macro, but way too much JPEG compression for a shot with so much detail. With a 97k file size, you had a lot more overhead and could have avoided a slightly grainy look to this.', '2009-03-18 01:13:14.000000', NULL, 1),
(5388281, 774332, 18403, '<td valign="top">You obviously don''t remember, because the operator comment was always: "Number please". But being older than dirt, I do remember and this is a fine photograph! Hope it does well.</td>', 'You obviously don''t remember, because the operator comment was always: "Number please". But being older than dirt, I do remember and this is a fine photograph! Hope it does well.', '2009-03-18 01:14:14.000000', NULL, 1),
(5388283, 773997, 63633, '<td valign="top">I have no idea what this is, but it is well shot. I guess it is probably scales in kilograms?</td>', 'I have no idea what this is, but it is well shot. I guess it is probably scales in kilograms?', '2009-03-18 01:15:06.000000', NULL, 1),
(5388285, 774302, 63633, '<td valign="top">Very cute - I love the Care Bears :)</td>', 'Very cute - I love the Care Bears :)', '2009-03-18 01:15:44.000000', NULL, 1),
(5388286, 774257, 18403, '<td valign="top">By my antiquated standards this is not very old, but nontheless a decent photo.</td>', 'By my antiquated standards this is not very old, but nontheless a decent photo.', '2009-03-18 01:16:36.000000', NULL, 1),
(5388288, 773862, 63633, '<td valign="top">We may be saying "Remember Those?" about all Fords very soon!</td>', 'We may be saying "Remember Those?" about all Fords very soon!', '2009-03-18 01:17:27.000000', NULL, 1),
(5388289, 774184, 63633, '<td valign="top">What a find! Great details, although the lighting is a bit harsh for my tastes.</td>', 'What a find! Great details, although the lighting is a bit harsh for my tastes.', '2009-03-18 01:18:38.000000', NULL, 1),
(5388290, 774131, 18403, '<td valign="top">Now yer talkin''!  All that is missing is the layer of cream on top where no bubbles form. Nice lighting!</td>', 'Now yer talkin''!  All that is missing is the layer of cream on top where no bubbles form. Nice lighting!', '2009-03-18 01:18:38.000000', NULL, 1),
(5388292, 773876, 63633, '<td valign="top">Don''t tell me you still have one of those!! Great subject, but I find the image too dark overall in my opinion. I guess it reminds me of playing computer games till all hours of the night ;)</td>', 'Don''t tell me you still have one of those!! Great subject, but I find the image too dark overall in my opinion. I guess it reminds me of playing computer games till all hours of the night ;)', '2009-03-18 01:20:48.000000', NULL, 1),
