(5388294, 774374, 63633, '<td valign="top">Tee Hee! Very funny!</td>', 'Tee Hee! Very funny!', '2009-03-18 01:21:45.000000', NULL, 1),
(5388295, 774251, 63633, '<td valign="top">Ha Ha! My Gran has a whole bunch of those too! We loved to wear them as little kids before we had our ears pierced :)</td>', 'Ha Ha! My Gran has a whole bunch of those too! We loved to wear them as little kids before we had our ears pierced :)', '2009-03-18 01:22:52.000000', NULL, 1),
(5388300, 774369, 18403, '<td valign="top">Durn!  Except for the laptop, this was my dorm room!  I like the glare of the lamp with its flare!</td>', 'Durn!  Except for the laptop, this was my dorm room!  I like the glare of the lamp with its flare!', '2009-03-18 01:24:41.000000', NULL, 1),
(5388301, 773762, 63633, '<td valign="top">A very pretty structure, but a bit too obscured by the trees I think.</td>', 'A very pretty structure, but a bit too obscured by the trees I think.', '2009-03-18 01:24:41.000000', NULL, 1),
(5388304, 773861, 63633, '<td valign="top">A striking image, but I don''t really understand the link to the challenge.</td>', 'A striking image, but I don''t really understand the link to the challenge.', '2009-03-18 01:25:41.000000', NULL, 1),
(5388309, 773911, 63633, '<td valign="top">Wow! It looks like this one is still open! Fantastic :) Composition wise, I would have liked more ground and less sky.</td>', 'Wow! It looks like this one is still open! Fantastic :) Composition wise, I would have liked more ground and less sky.', '2009-03-18 01:27:12.000000', NULL, 1),
(5388311, 774301, 96881, '<td valign="top">I used to have one of those as a kid.  They were cool...........<br/> <br/>Nice idea, nice composition, however I always remembered these are really brightly coloured.  Some additional Saturation and contrast on this to make the colours really pop I think would have worked better, rather than these more pale colours.<br/> <br/>Taking me back to my childhood.......</td>', 'I used to have one of those as a kid.  They were cool........... Nice idea, nice composition, however I always remembered these are really brightly coloured.  Some additional Saturation and contrast on this to make the colours really pop I think would have worked better, rather than these more pale colours. Taking me back to my childhood.......', '2009-03-18 01:28:27.000000', NULL, 1),
(5388312, 773157, 104023, '<td valign="top">This makes me want to pull out my speed graphic! I love it :)</td>', 'This makes me want to pull out my speed graphic! I love it :)', '2009-03-18 01:28:28.000000', NULL, 1),
(5388319, 773400, 63633, '<td valign="top">Great location - definitely forgotten! I find the image a bit muddy though - all shades of grey with no blacks or whites.</td>', 'Great location - definitely forgotten! I find the image a bit muddy though - all shades of grey with no blacks or whites.', '2009-03-18 01:30:37.000000', NULL, 1),
(5388320, 772809, 18403, '<td valign="top">Did someone actually forget that audio cassettes exist?  Nice use of grayscale and good control of DOF.</td>', 'Did someone actually forget that audio cassettes exist?  Nice use of grayscale and good control of DOF.', '2009-03-18 01:31:29.000000', NULL, 1),
(5388322, 773260, 63633, '<td valign="top">Looks like location, location, location!! A lovely well focussed image with pretty colours.</td>', 'Looks like location, location, location!! A lovely well focussed image with pretty colours.', '2009-03-18 01:32:19.000000', NULL, 1),
(5388325, 774302, 104023, '<td valign="top">Awww...Care Bears!!</td>', 'Awww...Care Bears!!', '2009-03-18 01:33:47.000000', NULL, 1),
