(5388334, 774167, 63633, '<td valign="top">Eek! I''d prefer to forget!! Haha :)</td>', 'Eek! I''d prefer to forget!! Haha :)', '2009-03-18 01:37:34.000000', NULL, 1),
(5388335, 774202, 18403, '<td valign="top">If these are models then they fooled me! Very nice use of water tint and texture with an interesting subject!</td>', 'If these are models then they fooled me! Very nice use of water tint and texture with an interesting subject!', '2009-03-18 01:38:03.000000', NULL, 1),
